  [a, b, c, d] = hashRound(b, a, d, c, 0x7, 0xC);
  [a, b, c, d] = hashRound(b, a, d, c, -0x17, 0x18);
  [a, b, c, d] = hashRound(a, b, c, d, -0x5, 0x1B);
